    # Журнал аудиту на рівні БД: автор зміни передається застосунком через SET LOCAL app.user_id
    op.execute("""
        CREATE FUNCTION trg_audit() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE
            v_user    bigint := nullif(current_setting('app.user_id', true), '')::bigint;
            v_new     jsonb;
            v_old     jsonb;
            v_payload jsonb;
        BEGIN
            IF TG_OP <> 'DELETE' THEN v_new := to_jsonb(NEW); END IF;
            IF TG_OP <> 'INSERT' THEN v_old := to_jsonb(OLD); END IF;

            IF TG_OP = 'UPDATE' THEN
                -- лише змінені поля; службові лічильники та хеш пароля не розкриваються
                SELECT jsonb_object_agg(k, jsonb_build_object('old', v_old -> k, 'new', v_new -> k))
                  INTO v_payload
                  FROM jsonb_object_keys(v_new) AS k
                 WHERE v_new -> k IS DISTINCT FROM v_old -> k
                   AND k NOT IN ('updated_at', 'last_login_at', 'token_version', 'password_hash');
                IF v_new ->> 'password_hash' IS DISTINCT FROM v_old ->> 'password_hash' THEN
                    v_payload := coalesce(v_payload, '{}'::jsonb) || '{"password": "changed"}'::jsonb;
                END IF;
                IF v_payload IS NULL THEN
                    RETURN NEW;
                END IF;
            ELSE
                v_payload := coalesce(v_new, v_old) - 'password_hash';
            END IF;

            INSERT INTO audit_log (user_id, action, entity, entity_key, payload)
            VALUES (v_user, TG_OP, TG_TABLE_NAME,
                    coalesce(v_new, v_old) ->> CASE WHEN TG_TABLE_NAME = 'pipeline_config'
                                                   THEN 'key' ELSE 'id' END,
                    v_payload);
            RETURN coalesce(NEW, OLD);
        END;
        $$;
    """)
